def save_photo():
    fd = frappe.form_dict or {}
    docname = fd.get("docname") or ""
    filedata = fd.get("filedata") or ""
    filename = fd.get("filename") or ("receiver_proof_" + str(frappe.utils.now_datetime()).replace("-","").replace(" ","_").replace(":","") + ".jpg")

    if not filedata:
        frappe.response["message"] = {"ok": False, "message": "No photo data provided."}
        return

    if "," in filedata:
        filedata = filedata.split(",", 1)[1]

    file_doc = frappe.get_doc({
        "doctype": "File",
        "file_name": filename,
        "content": filedata,
        "decode": True,
        "is_private": 0,
        "attached_to_doctype": "Stock Entry" if (docname and not docname.startswith("new-stock-entry")) else None,
        "attached_to_name": docname if (docname and not docname.startswith("new-stock-entry")) else None,
        "attached_to_field": "custom_receiver_photo" if (docname and not docname.startswith("new-stock-entry")) else None
    })
    file_doc.insert(ignore_permissions=True)
    frappe.response["message"] = {"ok": True, "file_url": file_doc.file_url, "file_name": file_doc.file_name}

save_photo()

