def sync_all_unlinked():
    unlinked = frappe.get_all(
        "Vehicle POS Invoice",
        filters={"docstatus": 1, "pos_invoice": ["in", ["", None]]},
        fields=["name", "company", "customer", "paid_amount", "total_amount"]
    )

    results = []
    for row in unlinked:
        name = row.name
        doc = frappe.get_doc("Vehicle POS Invoice", name)
        try:
            doc.create_erpnext_pos_invoice()
            frappe.db.commit()
            results.append({"name": name, "status": "synced", "pos_invoice": doc.pos_invoice})
        except Exception as e:
            frappe.db.rollback()
            results.append({"name": name, "status": "error", "error": str(e)})

    frappe.response["message"] = {
        "unlinked_found": len(unlinked),
        "results": results
    }

sync_all_unlinked()

def backfill():
    # Link every POS Invoice to its Vehicle POS Invoice
    vpis = frappe.get_all(
        "Vehicle POS Invoice",
        fields=["name", "pos_invoice", "vehicle", "customer"]
    )
    updated = []
    for v in vpis:
        if v.pos_invoice and frappe.db.exists("POS Invoice", v.pos_invoice):
            plate = frappe.db.get_value("Customer Vehicle", v.vehicle, "license_plate") if v.vehicle else ""
            frappe.db.set_value("POS Invoice", v.pos_invoice, {
                "custom_vehicle_pos_invoice": v.name,
                "custom_customer_vehicle": v.vehicle or "",
                "custom_plate_no": plate or ""
            }, update_modified=False)
            updated.append({"pos_invoice": v.pos_invoice, "vehicle_pos_invoice": v.name, "plate": plate})

    frappe.db.commit()
    frappe.response["message"] = {"status": "success", "updated": updated}

backfill()

